from collections import Counter

def rearrange_string(s: str) -> str:
    L = len(s)
    h = L // 2
    cnt = Counter(s)
    need = Counter()        # letter a -> unfilled 2nd-half slots whose partner is a
    state = {"T": 0, "f": h, "m": L % 2}   # typed slots, free pairs, free middle

    def feasible():
        T, f, m = state["T"], state["f"], state["m"]
        # letter c fits into typed slots not of type c, at most once per free pair, and the middle
        return all(k <= T - need[c] + f + m for c, k in cnt.items() if k)

    res = []
    for pos in range(L):
        if pos < h:
            kind, ban = "first", None
        elif L % 2 and pos == h:
            kind, ban = "mid", None
        else:
            kind, ban = "second", res[L - 1 - pos]
        for c in sorted(k for k, v in cnt.items() if v and k != ban):
            cnt[c] -= 1
            if kind == "first":
                state["f"] -= 1; state["T"] += 1; need[c] += 1
            elif kind == "mid":
                state["m"] = 0
            else:
                state["T"] -= 1; need[ban] -= 1
            if feasible():
                res.append(c)
                break
            cnt[c] += 1           # undo
            if kind == "first":
                state["f"] += 1; state["T"] -= 1; need[c] -= 1
            elif kind == "mid":
                state["m"] = 1
            else:
                state["T"] += 1; need[ban] += 1
        else:
            return "impossible"
    return "".join(res)
